-- 2) NEW 1007
INSERT INTO scholarships (id, title, provider, country, coverage_type, amount_usd_value, deadline, degree_levels, eligible_majors, min_gpa, min_ielts, financial_need_based, merit_based, description, requirements, website_url, eligible_countries, funding_type, tuition_coverage, living_allowance, travel_allowance, accommodation, application_fee, english_requirements, required_documents, application_url, opening_date, deadline_date, deadline_type, deadline_range_start, deadline_range_end, rounds, recurrence, expected_opening_period, expected_deadline_period, application_status, last_verified_at, last_updated_at, verification_status, source_reliability, source_url, notes, is_active, university_id, award_amount, award_currency, award_period, award_basis) VALUES
(1007, 'CityUHK Outstanding Athletes Entrance Scholarship (OAES) for Non-Local Students', 'City University of Hong Kong (CityU)', 'Hong Kong SAR', 'Partial Tuition', 0, 'Two-step process: apply for admission by the main-round direct application deadline (15 January 2027), then submit the OAES online application form with supporting documents by 30 January 2027 — applications received after the deadline are not considered.', '["Bachelor","Master"]', '["All Majors"]', NULL, NULL, false, true, 'The Outstanding Athletes Entrance Scholarship is the scholarship attached to CityUHK''s Student Athletes Admission Scheme, which since 1997 has admitted more than 1,600 students with high sports performance standards and is now extended to non-local athletes to strengthen the university''s sports teams. Non-local student-athletes admitted under the Scheme may receive up to HK$250,000 a year (about US$32,050 in the university''s approximation) — a package the university describes as equivalent to its academic Top Scholarship (record 556), and holders are not eligible for the Diversity Grant. For undergraduates the scholarship covers full tuition fees for the normal duration of study (a maximum of four years) and comes with a Residence Scholarship covering student residence hall fees; for master''s candidates it covers full or partial tuition for one year only, without the residence element. A selection panel assesses applicants with outstanding achievements in 18 listed sports — athletics, badminton, basketball, cross country, dragon boat, fencing, handball, karatedo, rugby, soccer, squash, swimming, table tennis, taekwondo, tennis, volleyball, water polo and woodball — and shortlisted candidates are recommended to the relevant colleges and schools for admission consideration. For undergraduates the award is renewed automatically each year provided the recipient keeps satisfactory sports performance and a CGPA of at least 2.5 by the end of each academic year.', 'Be a non-local applicant with outstanding achievements in one of the 18 listed sports, applying to a full-time UGC undergraduate programme or a one-year master''s programme at CityUHK. The process has two steps: first submit the online admission application (undergraduate International Admissions for non-Mainland applicants, the Mainland Gaokao/non-Gaokao routes, or the master''s admission route — noting each master''s programme''s own deadline; the main-round direct application deadline is 15 January 2027), choosing no more than one Flagship Programme at undergraduate level; then submit the OAES online application form with all supporting documents by 30 January 2027. Applications are processed only when all required documents are received, and further documents may be requested. Admission requirements for the academic programme (including English) still apply — the panel recommends shortlisted candidates to colleges/schools for admission consideration. After a confirmed offer you must pay the confirmation fee and register for student residence by the specified deadlines or be treated as having withdrawn. Recipients must inform the OAES coordinator of any recent or previous injury: arriving injured and unable to compete in inter-university competitions may lead to a grace period and possible loss of the scholarship in the coming year.', 'https://www.cityu.edu.hk/sds/physical-education-wellness-and-sports/student-athletes-admission/outstanding-athletes-entrance', '["All"]', 'Sports talent-based', 'Full tuition for undergraduate recipients (normal duration, max four years) plus the Residence Scholarship covering hall fees; full or partial tuition for master''s recipients for one year only', NULL, NULL, NULL, NULL, 'No scholarship-specific English score is published; applicants must meet CityUHK''s admission English language requirement for their qualification, and TOEFL/IELTS certificates are among the OAES supporting documents (check the official admissions page).', '["CityUHK online admission application (undergraduate International Admissions, Mainland, or master''s route as applicable)","OAES online application form","Recommendation letter(s) proving current sports performance (within 2 years), signed by the nominator, team coach or team manager","Academic transcripts including TOEFL and/or IELTS certificates","Sports CV/resume with web links to official-match competition videos (full match or 15-20 minutes of play, identifying the applicant)","Physician''s letter (issued within 3 months of application) confirming fitness to compete at the current level of play","University confirmation email for the academic-programme application"]', 'https://www.cityu.edu.hk/sds/physical-education-wellness-and-sports/student-athletes-admission/outstanding-athletes-entrance', NULL, '2027-01-30', 'fixed', NULL, NULL, '[]', 'annual', 'With the yearly admission cycle (OAES form follows the admission application)', 'Late January (30 January 2027 for the current round; admission application by the 15 January main-round deadline)', 'open', '2026-10-30 10:00:00+05', '2026-10-30 10:00:00+05', 'verified', 10, 'https://www.cityu.edu.hk/sds/physical-education-wellness-and-sports/student-athletes-admission/outstanding-athletes-entrance', 'NEW in Enrichment Batch 43 (2026-10-30), written from the first-hand read of CityUHK''s official OAES page for non-local students (source 3195, read in full: scheme extending the since-1997 Student Athletes Admission Scheme to non-local athletes, up to HK$250,000 a year equivalent to the Top Scholarship on record 556, full tuition plus the Residence Scholarship for undergraduates, one-year full/partial tuition for master''s candidates, 18 listed sports, panel selection, two-step application with the 30 January 2027 OAES deadline, renewal on satisfactory sports performance and CGPA of at least 2.5). The scheme surfaced on the current Entrance Scholarship page read in Pass 135 (source 3188) and is recorded here as its own individually verified award rather than folded into the academic entrance-scholarship record; no athlete scheme existed in the catalogue before today. award_amount stores the published maximum (HK$250,000, per year, range basis), with amount_usd_value 0 because the university publishes in HKD (its own US$32,050 approximation is quoted in the description but not structured). min_gpa/min_ielts NULL: the only GPA figure on the page is the 2.5 undergraduate renewal condition, and English requirement is left to programme admission.', true, 63, 250000, 'HKD', 'year', 'range');

